<?php

/**
 * Project: PPL Study
 * File: reset.php
 * Module Type: Recovery Utility
 *
 * Purpose:
 *   Provides an explicit emergency administrator password reset guarded by the
 *   deployment-specific setup_key generated by install.php.
 *
 * Responsibilities:
 *   - Refuse operation before installation
 *   - Require the secret setup_key from config.php
 *   - Require a new administrator password of at least 15 characters
 *   - Update or create exactly one administrator account
 *   - Avoid exposing database credentials or password hashes
 *
 * Author: Rudolf Klusal
 * License: MIT License for application code. See LICENSE.
 *
 * Notes:
 *   - This utility is intentionally independent of the normal admin session.
 *   - After emergency use, rotate setup_key in config.php if it may have leaked.
 *   - Keep comments and docstrings intact when modifying this file.
 */

declare(strict_types=1);

$root = __DIR__;
$configPath = $root . '/config.php';
if (!is_file($configPath)) {
    http_response_code(503);
    exit('PPL Study installation is required. Run install.php first.');
}

$config = require $configPath;
if (!is_array($config)) {
    http_response_code(500);
    exit('Invalid config.php.');
}

session_name('ppl_study_recovery');
session_start();
if (!isset($_SESSION['recovery_csrf'])) {
    $_SESSION['recovery_csrf'] = bin2hex(random_bytes(24));
}

/** Escape one recovery page value. */
function recovery_e(?string $value): string
{
    return htmlspecialchars((string) $value, ENT_QUOTES | ENT_SUBSTITUTE, 'UTF-8');
}

/** Connect using the installed database configuration. */
function recovery_db(array $config): PDO
{
    $db = $config['database'] ?? [];
    if (!is_array($db)) {
        throw new RuntimeException('Database configuration is required.');
    }
    $dsn = 'mysql:host=' . (string) ($db['host'] ?? 'localhost')
        . ';port=' . (int) ($db['port'] ?? 3306)
        . ';dbname=' . (string) ($db['name'] ?? '')
        . ';charset=' . (string) ($db['charset'] ?? 'utf8mb4');
    return new PDO($dsn, (string) ($db['user'] ?? ''), (string) ($db['password'] ?? ''), [
        PDO::ATTR_ERRMODE => PDO::ERRMODE_EXCEPTION,
        PDO::ATTR_DEFAULT_FETCH_MODE => PDO::FETCH_ASSOC,
        PDO::ATTR_EMULATE_PREPARES => false,
    ]);
}

$error = '';
$success = '';
try {
    if (($_SERVER['REQUEST_METHOD'] ?? 'GET') === 'POST') {
        if (!hash_equals((string) $_SESSION['recovery_csrf'], (string) ($_POST['csrf'] ?? ''))) {
            throw new RuntimeException('Invalid recovery session. Reload the page.');
        }
        $expectedKey = (string) ($config['setup_key'] ?? '');
        $providedKey = trim((string) ($_POST['setup_key'] ?? ''));
        if ($expectedKey === '' || !hash_equals($expectedKey, $providedKey)) {
            usleep(400000);
            throw new RuntimeException('Invalid setup key.');
        }
        $username = trim((string) ($_POST['username'] ?? 'admin'));
        $password = (string) ($_POST['password'] ?? '');
        $passwordAgain = (string) ($_POST['password_again'] ?? '');
        if ($username === '' || strlen($username) > 190) {
            throw new RuntimeException('Username is required and must be at most 190 characters.');
        }
        if (mb_strlen($password, 'UTF-8') < 15) {
            throw new RuntimeException('New password must contain at least 15 characters.');
        }
        if (!hash_equals($password, $passwordAgain)) {
            throw new RuntimeException('Enter the same password in both password fields.');
        }
        $pdo = recovery_db($config);
        $now = gmdate('Y-m-d H:i:s');
        $columns = $pdo->query('SHOW COLUMNS FROM users')->fetchAll(PDO::FETCH_COLUMN);
        $present = array_fill_keys(array_map('strval', $columns), true);
        $schemaReady = count(array_filter(['display_name', 'must_change_password', 'temporary_password_consumed_at', 'active', 'created_by_user_id', 'last_login_at', 'password_changed_at'], static fn (string $column): bool => isset($present[$column]))) === 7;
        if ($schemaReady) {
            $stmt = $pdo->prepare("INSERT INTO users (username, display_name, password_hash, role, must_change_password, temporary_password_consumed_at, active, created_by_user_id, last_login_at, password_changed_at, created_at, updated_at)
                VALUES (?, ?, ?, 'admin', 0, NULL, 1, NULL, NULL, ?, ?, ?)
                ON DUPLICATE KEY UPDATE display_name = VALUES(display_name), password_hash = VALUES(password_hash), role = 'admin', must_change_password = 0, temporary_password_consumed_at = NULL, active = 1, password_changed_at = VALUES(password_changed_at), updated_at = VALUES(updated_at)");
            $stmt->execute([$username, $username, password_hash($password, PASSWORD_DEFAULT), $now, $now, $now]);
        } else {
            $stmt = $pdo->prepare("INSERT INTO users (username, password_hash, role, created_at, updated_at) VALUES (?, ?, 'admin', ?, ?) ON DUPLICATE KEY UPDATE password_hash = VALUES(password_hash), role = 'admin', updated_at = VALUES(updated_at)");
            $stmt->execute([$username, password_hash($password, PASSWORD_DEFAULT), $now, $now]);
        }
        $_SESSION['recovery_csrf'] = bin2hex(random_bytes(24));
        $success = 'Administrator credentials were reset. You can now sign in.';
    }
} catch (Throwable $exception) {
    $error = $exception->getMessage();
}

$base = rtrim((string) ($config['base_url'] ?? ''), '/');
?>
<!doctype html>
<html lang="en">
<head>
    <meta charset="utf-8">
    <meta name="viewport" content="width=device-width,initial-scale=1">
    <meta name="robots" content="noindex,nofollow">
    <title>PPL Study Recovery</title>
    <style>
        body{margin:0;min-height:100vh;display:grid;place-items:center;background:#f4f8fb;color:#10253f;font-family:system-ui,-apple-system,"Segoe UI",sans-serif}.card{width:min(92vw,470px);background:#fff;border:1px solid #d9e4ec;border-radius:18px;padding:28px;box-shadow:0 16px 38px rgba(16,37,63,.09)}h1{margin:.2rem 0 .5rem}.eyebrow{font-size:12px;font-weight:800;letter-spacing:.12em;text-transform:uppercase;color:#166497}label{display:flex;flex-direction:column;gap:6px;margin-top:14px;font-size:13px;font-weight:700;color:#506174}input{padding:10px;border:1px solid #cfdbe4;border-radius:8px;font:inherit}.button{display:inline-flex;margin-top:18px;padding:10px 15px;border:0;border-radius:9px;background:#10253f;color:#fff;font-weight:700;text-decoration:none;cursor:pointer}.flash{padding:11px 13px;border-radius:8px;margin:14px 0}.error{background:#fff0ee;color:#a63b36}.success{background:#e9f7f1;color:#11734f}.hint{color:#718096;font-size:13px}code{background:#edf2f6;padding:2px 4px;border-radius:4px}
    </style>
</head>
<body><main class="card">
    <span class="eyebrow">PPL Study</span><h1>Administrator recovery</h1>
    <p class="hint">Copy the <code>setup_key</code> value from the installed <code>config.php</code> into the field below.</p>
    <?php if ($error !== ''): ?><div class="flash error"><?= recovery_e($error) ?></div><?php endif; ?>
    <?php if ($success !== ''): ?><div class="flash success"><?= recovery_e($success) ?></div><?php endif; ?>
    <form method="post">
        <input type="hidden" name="csrf" value="<?= recovery_e((string) $_SESSION['recovery_csrf']) ?>">
        <label>Setup key<input type="password" name="setup_key" autocomplete="off" required></label>
        <label>Administrator username<input name="username" value="admin" autocomplete="username" required></label>
        <label>New password<input type="password" name="password" minlength="15" autocomplete="new-password" required></label>
        <label>Repeat new password<input type="password" name="password_again" minlength="15" autocomplete="new-password" required></label>
        <button class="button" type="submit">Reset administrator</button>
    </form>
    <?php if ($base !== ''): ?><p><a href="<?= recovery_e($base . '/login') ?>">Back to login</a></p><?php endif; ?>
</main></body></html>
